/**
 * @summary Create a share link for a project
 */
export const getCreateShareLinkUrl = () => {
  return `/api/share`;
};

export const createShareLink = async (
  createShareRequest: CreateShareRequest,
  options?: RequestInit,
): Promise<ShareLink> => {
  return customFetch<ShareLink>(getCreateShareLinkUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(createShareRequest),
  });
};

export const getCreateShareLinkMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createShareLink>>,
    TError,
    { data: BodyType<CreateShareRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof createShareLink>>,
  TError,
  { data: BodyType<CreateShareRequest> },
  TContext
> => {
  const mutationKey = ["createShareLink"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof createShareLink>>,
    { data: BodyType<CreateShareRequest> }
  > = (props) => {
    const { data } = props ?? {};

    return createShareLink(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type CreateShareLinkMutationResult = NonNullable<
  Awaited<ReturnType<typeof createShareLink>>
>;
export type CreateShareLinkMutationBody = BodyType<CreateShareRequest>;
export type CreateShareLinkMutationError = ErrorType<unknown>;

/**
 * @summary Create a share link for a project
 */
export const useCreateShareLink = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof createShareLink>>,
    TError,
    { data: BodyType<CreateShareRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof createShareLink>>,
  TError,
  { data: BodyType<CreateShareRequest> },
  TContext
> => {
  return useMutation(getCreateShareLinkMutationOptions(options));
};

/**
 * @summary Get a shared project by token
 */
export const getGetSharedProjectUrl = (token: string) => {
  return `/api/share/${token}`;
};

export const getSharedProject = async (
  token: string,
  options?: RequestInit,
): Promise<SharedProjectView> => {
  return customFetch<SharedProjectView>(getGetSharedProjectUrl(token), {
    ...options,
    method: "GET",
  });
};

export const getGetSharedProjectQueryKey = (token: string) => {
  return [`/api/share/${token}`] as const;
};

export const getGetSharedProjectQueryOptions = <
  TData = Awaited<ReturnType<typeof getSharedProject>>,
  TError = ErrorType<Error>,
>(
  token: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getSharedProject>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetSharedProjectQueryKey(token);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getSharedProject>>
  > = ({ signal }) => getSharedProject(token, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!token,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getSharedProject>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetSharedProjectQueryResult = NonNullable<
  Awaited<ReturnType<typeof getSharedProject>>
>;
export type GetSharedProjectQueryError = ErrorType<Error>;

/**
 * @summary Get a shared project by token
 */

export function useGetSharedProject<
  TData = Awaited<ReturnType<typeof getSharedProject>>,
  TError = ErrorType<Error>,
>(
  token: string,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getSharedProject>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetSharedProjectQueryOptions(token, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
